<?php
declare(strict_types=1);

final class LearningCoursesSeeder
{
    public static function run(PDO $db): int
    {
        $items = self::items();
        $db->beginTransaction();
        try { foreach ($items as $item) self::store($db, $item); self::appendMoreLessons($db); self::appendStructuredLessons($db); self::expandExistingReadings($db); $db->commit(); }
        catch (Throwable $e) { $db->rollBack(); throw $e; }
        return count($items);
    }
    private static function store(PDO $db, array $item): void
    {
        $q=$db->prepare('SELECT id FROM course_categories WHERE code=?'); $q->execute([$item['category']]); $category=(int)$q->fetchColumn();
        if (!$category) throw new RuntimeException('Categoria de curso inexistente.');
        $duration=(int)$item['minutes']+108;
        $q=$db->prepare("INSERT INTO courses(category_id,level,title,slug,short_description,description,estimated_minutes,status,is_free,created_at,updated_at,published_at) VALUES(?,?,?,?,?,?,?,'published',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),level=VALUES(level),title=VALUES(title),short_description=VALUES(short_description),description=VALUES(description),estimated_minutes=VALUES(estimated_minutes),status='published',updated_at=CURRENT_TIMESTAMP");
        $q->execute([$category,$item['level'],$item['title'],$item['slug'],$item['short'],$item['description'],$duration]);
        $q=$db->prepare('SELECT id FROM courses WHERE slug=?');$q->execute([$item['slug']]);$id=(int)$q->fetchColumn();
        $coverImages = [
            'botanica-desde-cero' => 'front/images/botanica-desde-cero-cover.png',
            'plantas-felices-en-casa' => 'front/images/plantas-felices-en-casa-cover.png',
            'tu-primer-huerto' => 'front/images/tu-primer-huerto-cover.png',
        ];
        if (isset($coverImages[$item['slug']])) {
            $db->prepare('UPDATE courses SET cover_image_url=? WHERE id=?')->execute([$coverImages[$item['slug']],$id]);
        }
        $existing=$db->prepare('SELECT id FROM course_modules WHERE course_id=? ORDER BY position LIMIT 1');$existing->execute([$id]);$module=(int)$existing->fetchColumn();
        if(!$module){
            $out=$db->prepare('INSERT INTO course_learning_outcomes(course_id,body,position)VALUES(?,?,?)');foreach($item['outcomes'] as $i=>$v)$out->execute([$id,$v,$i+1]);
            $pre=$db->prepare('INSERT INTO course_prerequisites(course_id,body,position)VALUES(?,?,?)');foreach($item['prerequisites'] as $i=>$v)$pre->execute([$id,$v,$i+1]);
            $tag=$db->prepare('INSERT INTO course_tags(course_id,tag_id,weight,is_required) SELECT ?,id,100,0 FROM tags WHERE code=?');foreach($item['tags'] as $v)$tag->execute([$id,$v]);
            $mod=$db->prepare('INSERT INTO course_modules(course_id,title,description,position,estimated_minutes,is_required)VALUES(?,?,?,?,?,1)');$mod->execute([$id,$item['module'],$item['description'],1,$duration]);$module=(int)$db->lastInsertId();
        } else {$db->prepare('UPDATE course_modules SET estimated_minutes=? WHERE id=?')->execute([$duration,$module]);}
        $lesson=$db->prepare('INSERT INTO lessons(module_id,title,description,position,estimated_minutes,is_required,is_preview)VALUES(?,?,?,?,?,1,?)');$findLesson=$db->prepare('SELECT id FROM lessons WHERE module_id=? AND title=?');$countLessons=$db->prepare('SELECT COUNT(*) FROM lessons WHERE module_id=?');$block=$db->prepare('INSERT INTO lesson_blocks(lesson_id,type,title,body,content_data,position,is_required,low_bandwidth)VALUES(?,?,?,?,?,?,?,0)');$ref=$db->prepare('INSERT INTO content_references(course_id,lesson_id,title,url,source_type,notes,position)VALUES(?,?,?,?,?,?,?)');
        foreach($item['lessons'] as $i=>$l){$findLesson->execute([$module,$l[0]]);if($findLesson->fetchColumn())continue;$countLessons->execute([$module]);$position=(int)$countLessons->fetchColumn()+1;$lesson->execute([$module,$l[0],$l[1],$position,$l[2],$position===1]);$lessonId=(int)$db->lastInsertId();$block->execute([$lessonId,'text',$l[0],$l[3],null,1,1]);$block->execute([$lessonId,'quiz','Comprobacion',null,json_encode(['question'=>$l[4],'options'=>$l[5],'correct_option'=>$l[6],'feedback'=>$l[7]],JSON_UNESCAPED_UNICODE),2,1]);$ref->execute([$id,$lessonId,$item['reference'][0],$item['reference'][1],'external',$item['reference'][2],$position]);}
        self::storeReference($db,$id,'OpenAI: IA para estructura y redaccion de cursos','https://openai.com/','ai','Asistencia de IA en la estructura y redaccion inicial del curso; requiere revision editorial humana.',99);
        if ($item['slug'] === 'botanica-desde-cero') {
            $prompt = "Fotograf\u{00ED}a bot\u{00E1}nica realista de una planta silvestre con hojas, tallo y flores claramente visibles, creciendo junto a otras especies peque\u{00F1}as en un jard\u{00ED}n natural. Luz suave de ma\u{00F1}ana, colores fieles a la naturaleza y fondo verde desenfocado. Composici\u{00F3}n limpia, educativa y acogedora, adecuada como portada de un curso de introducci\u{00F3}n a la bot\u{00E1}nica. Sin personas, texto, etiquetas ni elementos artificiales.";
            self::storeReference($db,$id,'Imagen generada con IA: Pradera de Coneflowers al Sol','front/images/botanica-desde-cero-cover.png','ai','Referencia descriptiva en formato APA: Pradera de Coneflowers al Sol [imagen generada con IA]. (s. f.). Autor y herramienta no especificados. Prompt utilizado: ' . $prompt,100);
        }
        if ($item['slug'] === 'plantas-felices-en-casa') {
            $prompt = "Fotograf\u{00ED}a realista de una colecci\u{00F3}n variada de plantas de interior \u{2014}monstera, potus y helechos\u{2014} junto a una ventana luminosa. Hojas sanas con distintas formas y tonos verdes, macetas de cer\u{00E1}mica en colores neutros y luz natural c\u{00E1}lida. Composici\u{00F3}n ordenada y tranquila, adecuada como portada de un curso sobre iluminaci\u{00F3}n, riego y cuidado de plantas de interior. Sin personas, texto ni elementos artificiales.";
            $title = "Imagen generada con IA: Jard\u{00ED}n interior junto a la ventana";
            self::storeReference($db,$id,$title,'front/images/plantas-felices-en-casa-cover.png','ai','Referencia descriptiva en formato APA: Jard\u{00ED}n interior junto a la ventana [imagen generada con IA]. (s. f.). Autor y herramienta no especificados. Prompt utilizado: ' . $prompt,100);
        }
        if ($item['slug'] === 'tu-primer-huerto') {
            $prompt = "Fotograf\u{00ED}a realista de un peque\u{00F1}o huerto comestible con lechugas, tomates maduros, hierbas arom\u{00E1}ticas y brotes creciendo en camas de cultivo. Luz natural de ma\u{00F1}ana, tierra visible y abundante vegetaci\u{00F3}n fresca; composici\u{00F3}n que transmita cosecha y aprendizaje pr\u{00E1}ctico. Adecuada como portada de un curso para principiantes sobre c\u{00F3}mo crear un huerto. Sin personas, texto ni herramientas en primer plano.";
            self::storeReference($db,$id,'Imagen generada con IA: Huerto elevado lleno de vida','front/images/tu-primer-huerto-cover.png','ai','Referencia descriptiva en formato APA: Huerto elevado lleno de vida [imagen generada con IA]. (s. f.). Autor y herramienta no especificados. Prompt utilizado: ' . $prompt,100);
        }
    }
    private static function storeReference(PDO $db,int $courseId,string $title,?string $url,string $sourceType,string $notes,int $position): void
    {
        $find=$db->prepare('SELECT id FROM content_references WHERE course_id=? AND lesson_id IS NULL AND source_type=? AND (title=? OR url=?) ORDER BY id LIMIT 1');
        $find->execute([$courseId,$sourceType,$title,$url]);
        $id=(int)$find->fetchColumn();
        if($id){
            $db->prepare('UPDATE content_references SET url=?,notes=?,position=? WHERE id=?')->execute([$url,$notes,$position,$id]);
            return;
        }
        $db->prepare('INSERT INTO content_references(course_id,lesson_id,title,url,source_type,notes,position) VALUES(?,NULL,?,?,?,?,?)')->execute([$courseId,$title,$url,$sourceType,$notes,$position]);
    }
    private static function appendMoreLessons(PDO $db): void
    {
        $extra = [
            ['botanica-desde-cero','Comparar sin adivinar','Compara dos plantas con rasgos observables y registra qué evidencia sostiene cada diferencia.','Elige dos hojas. Describe forma, margen, nervaduras y disposición. No concluyas que son especies distintas por un solo rasgo; contrasta varios caracteres y consulta una clave o fuente botánica confiable.',['¿Qué comparación aporta mejor evidencia?',['Comparar varios caracteres visibles','Comparar solo el tamaño de la maceta','Adivinar por el color'],0,'Usar varios caracteres observables reduce conclusiones apresuradas.']],
            ['botanica-desde-cero','De la observación a una pregunta','Formula una pregunta que pueda responderse mediante observaciones repetidas.','Una pregunta útil delimita qué observar, dónde y durante cuánto tiempo. Registra condiciones para no confundir coincidencia con causa.',['¿Cuál es una pregunta comprobable?',['¿Por qué es bonita?','¿Cuántas hojas nuevas aparecen esta semana?','¿Le gusta la música?'],1,'La pregunta define algo observable y un periodo.']],
            ['botanica-desde-cero','Ficha de identificación responsable','Integra tus notas y reconoce cuándo la evidencia no basta para identificar una especie.','Una ficha útil incluye fotografías de varias partes, ubicación general, fecha y fuente consultada. Si los rasgos no bastan, registra “identificación pendiente” y evita consumir o manipular una planta desconocida.',['¿Qué hacer si la identificación es incierta?',['Publicarla como segura','Marcarla pendiente y reunir más evidencia','Probarla para identificarla'],1,'La incertidumbre debe quedar explícita; no pruebes plantas desconocidas.']],
            ['plantas-felices-en-casa','Diagnostica antes de cambiar cuidados','Investiga hojas amarillas sin asumir una causa única.','Revisa el patrón del síntoma, humedad del sustrato, drenaje, luz reciente y presencia de plagas. Cambia una condición a la vez y observa la respuesta; síntomas parecidos pueden tener causas distintas.',['¿Cuál es el primer paso razonable?',['Aplicar fertilizante de inmediato','Revisar condiciones y patrón del síntoma','Cortar todas las hojas'],1,'Reúne evidencia antes de intervenir.']],
            ['plantas-felices-en-casa','Trasplanta solo cuando haga falta','Reconoce señales para revisar el cepellón y prepara un recipiente con drenaje.','Raíces que salen por los orificios o un sustrato que se seca inusualmente rápido pueden justificar revisar la maceta. Elige un recipiente solo un tamaño mayor y conserva raíces sanas.',['¿Qué característica debe tener la nueva maceta?',['Ser mucho más grande','Tener drenaje y ser apenas mayor','No tener salida de agua'],1,'Un salto excesivo de tamaño dificulta controlar la humedad.']],
            ['plantas-felices-en-casa','Plan de cuidado semanal','Construye una rutina flexible y evita regar solo por calendario.','Revisa luz, humedad, hojas y drenaje. La frecuencia depende de especie, estación, recipiente y ambiente; registra lo observado y ajusta gradualmente.',['¿Qué determina cuándo regar?',['Un día fijo para todas','La humedad del sustrato y las condiciones','El color de la maceta'],1,'Evalúa cada planta y su entorno.']],
            ['tu-primer-huerto','Siembra y profundidad','Planifica la profundidad y separación indicadas para cada cultivo.','Las necesidades de germinación varían entre especies. Sigue las instrucciones del proveedor, mantén humedad adecuada sin encharcar y etiqueta cada siembra con cultivo y fecha.',['¿Qué guía la profundidad de siembra?',['Una regla idéntica para todas','Las indicaciones del cultivo','El tamaño del recipiente únicamente'],1,'Las instrucciones dependen de la especie.']],
            ['tu-primer-huerto','Observa plagas antes de intervenir','Inspecciona el envés de las hojas y registra señales antes de decidir.','Busca insectos, melaza, manchas o daño nuevo. Aísla una maceta si sospechas plaga y confirma la identificación antes de elegir un control. Sigue la etiqueta de cualquier producto.',['¿Qué conviene hacer antes de tratar?',['Identificar la plaga y evaluar el daño','Mezclar productos','Aplicar la dosis más alta'],0,'La identificación ayuda a elegir medidas proporcionales.']],
            ['tu-primer-huerto','Cosecha y evaluación del ciclo','Registra qué funcionó y qué cambiarás en la siguiente siembra.','Anota fechas, horas de sol, riegos, incidencias y rendimiento observado. Compara el resultado con el espacio disponible y ajusta una variable en el siguiente ciclo.',['¿Qué permite mejorar la siguiente siembra?',['Llevar registro y cambiar una variable','Cambiar todo sin anotar','Usar más fertilizante por defecto'],0,'Los registros permiten aprender del ciclo real.']],
        ];
        $module=$db->prepare('SELECT m.id FROM course_modules m JOIN courses c ON c.id=m.course_id WHERE c.slug=? ORDER BY m.position LIMIT 1');
        $find=$db->prepare('SELECT id FROM lessons WHERE module_id=? AND title=?');
        $count=$db->prepare('SELECT COUNT(*) FROM lessons WHERE module_id=?');
        $lesson=$db->prepare('INSERT INTO lessons(module_id,title,description,position,estimated_minutes,is_required,is_preview) VALUES(?,?,?,?,15,1,0)');
        $block=$db->prepare('INSERT INTO lesson_blocks(lesson_id,type,title,body,content_data,position,is_required,low_bandwidth) VALUES(?,?,?,?,?,?,1,0)');
        $practiceCheck=$db->prepare("SELECT COUNT(*) FROM lesson_blocks WHERE lesson_id=? AND type='practice'");
        $practiceInstructions=['Ficha de identificación responsable'=>'Registra nombre provisional, fecha, ubicación general, rasgos observados y fuente consultada. Si no puedes identificarla, escribe “pendiente”. No recolectes ni consumas la planta.','Diagnostica antes de cambiar cuidados'=>'Describe el síntoma, humedad del sustrato, luz y drenaje de una planta. Propón qué observarías después antes de cambiar su cuidado.','Observa plagas antes de intervenir'=>'Anota señales en el envés de una hoja, daño visible y fecha. No apliques productos; deja la identificación como pendiente si no estás seguro.','Cosecha y evaluación del ciclo'=>'Registra cultivo, fecha de siembra, horas de sol, riegos e incidencias del ciclo. Escribe una variable que probarías ajustar la próxima vez.'];
        foreach($extra as [$slug,$title,$description,$body,$quiz]){
            $module->execute([$slug]);$moduleId=(int)$module->fetchColumn();if(!$moduleId)continue;
            $find->execute([$moduleId,$title]);$existingLesson=(int)$find->fetchColumn();if($existingLesson){if(isset($practiceInstructions[$title])){$practiceCheck->execute([$existingLesson]);if(!(int)$practiceCheck->fetchColumn())$block->execute([$existingLesson,'practice','Entrega tu registro práctico',null,json_encode(['instructions'=>$practiceInstructions[$title],'review_status'=>'pending_review'],JSON_UNESCAPED_UNICODE),3]);}continue;}
            $count->execute([$moduleId]);$position=(int)$count->fetchColumn()+1;
            $lesson->execute([$moduleId,$title,$description,$position]);$lessonId=(int)$db->lastInsertId();
            $block->execute([$lessonId,'text',$title,$body,null,1]);
            $block->execute([$lessonId,'quiz','Comprueba lo aprendido',null,json_encode(['question'=>$quiz[0],'options'=>$quiz[1],'correct_option'=>$quiz[2],'feedback'=>$quiz[3]],JSON_UNESCAPED_UNICODE),2]);
            if(isset($practiceInstructions[$title]))$block->execute([$lessonId,'practice','Entrega tu registro práctico',null,json_encode(['instructions'=>$practiceInstructions[$title],'review_status'=>'pending_review'],JSON_UNESCAPED_UNICODE),3]);
        }
    }

    private static function appendStructuredLessons(PDO $db): void
    {
        $lessons = [
            ['slug'=>'botanica-desde-cero','title'=>'Lectura: construir una observación botánica','description'=>'Una guía de lectura para separar lo que observas de lo que todavía necesitas comprobar.','minutes'=>18,'source'=>['Royal Botanic Gardens, Kew. (s. f.). Plants of the World Online: About POWO.','https://powo.science.kew.org/about'],'blocks'=>[
                ['type'=>'text','title'=>'Empieza por describir','body'=>"Una observación botánica comienza con rasgos visibles, no con una identificación apresurada. Registra qué parte de la planta observas y describe forma, tamaño aproximado, textura, color y disposición. Indica también qué rasgo no pudiste observar.\n\nLa descripción debe permitir que otra persona entienda qué viste aunque todavía no conozca el nombre de la planta."],
                ['type'=>'text','title'=>'Separa evidencia e interpretación','body'=>"“Hay tres hojas nuevas desde el lunes” es una observación delimitada por un periodo. “La planta está feliz” es una interpretación que no explica qué evidencia la sostiene. Puedes conservar una interpretación como hipótesis, siempre que la señales como tal.\n\nAnota fecha, lugar general, condiciones relevantes y si la planta fue fotografiada. Compara registros hechos en condiciones parecidas antes de afirmar que algo cambió."],
                ['type'=>'text','title'=>'Usa la identificación como una hipótesis','body'=>"Los nombres comunes pueden variar entre regiones y una misma planta puede recibir más de uno. Para consultar un nombre científico, contrasta los rasgos con una fuente botánica identificable y registra el nombre de la fuente y la fecha de consulta.\n\nPlants of the World Online, de Kew, reúne información taxonómica y de distribución para plantas vasculares. La propia plataforma advierte que su información es orientativa y que las decisiones taxonómicas pueden actualizarse. Si los rasgos no bastan, deja la identificación como pendiente."],
            ]],
            ['slug'=>'botanica-desde-cero','title'=>'Práctica: expediente de una planta','description'=>'Elabora un registro verificable a partir de una planta que puedas observar sin dañarla.','minutes'=>25,'source'=>['Royal Botanic Gardens, Kew. (s. f.). Plants of the World Online: About POWO.','https://powo.science.kew.org/about'],'blocks'=>[
                ['type'=>'practice','title'=>'Entrega tu expediente','instructions'=>"Elige una planta que puedas observar de forma segura. No la cortes, pruebes ni manipules si no conoces la especie. Completa tu respuesta con estos apartados:\n\n1. Fecha y lugar general de observación.\n2. Tipo de ambiente y condiciones visibles, como luz aproximada o humedad del sustrato.\n3. Descripción de tallo y hojas; añade flor, fruto o semilla solo si están presentes.\n4. Una fotografía propia o una descripción de la imagen que usarías.\n5. Nombre provisional y fuente consultada, o la frase “identificación pendiente”.\n6. Una pregunta que necesitarías investigar para confirmar tu hipótesis.\n\nCierra indicando qué dato es observación directa y cuál es interpretación. No incluyas una dirección privada ni afirmes una especie si no tienes evidencia suficiente."]
            ]],
            ['slug'=>'botanica-desde-cero','title'=>'Examen de fundamentos botánicos','description'=>'Autoevaluación de cinco reactivos sobre observación, nomenclatura y uso responsable de fuentes.','minutes'=>20,'source'=>['Royal Botanic Gardens, Kew. (s. f.). Plants of the World Online: About POWO.','https://powo.science.kew.org/about'],'blocks'=>[
                ['type'=>'quiz','title'=>'Reactivo 1 de 5','question'=>'¿Cuál frase describe una observación que puede verificarse?','options'=>['La planta está triste','Aparecieron dos hojas nuevas en siete días','La planta quiere más espacio'],'correct'=>1,'feedback'=>'Una observación delimita un cambio y el periodo en que se registró.'],
                ['type'=>'quiz','title'=>'Reactivo 2 de 5','question'=>'Si no puedes observar flores ni frutos, ¿qué conviene hacer?','options'=>['Inventar el rasgo faltante','Registrar qué partes sí observaste y dejar la identificación abierta','Identificarla solo por el color de la maceta'],'correct'=>1,'feedback'=>'Registrar los límites de la observación evita presentar una hipótesis como certeza.'],
                ['type'=>'quiz','title'=>'Reactivo 3 de 5','question'=>'¿Qué dato ayuda a que otra persona revise una identificación consultada?','options'=>['Nombre de la fuente y fecha de consulta','Opinión sin contexto','Solo el nombre común'],'correct'=>0,'feedback'=>'La fuente y la fecha permiten rastrear y volver a consultar la evidencia.'],
                ['type'=>'quiz','title'=>'Reactivo 4 de 5','question'=>'¿Qué describe mejor una hipótesis?','options'=>['Una explicación posible que aún debe contrastarse','Un hecho confirmado por definición','Un nombre común'],'correct'=>0,'feedback'=>'Una hipótesis propone una explicación que todavía requiere evidencia.'],
                ['type'=>'quiz','title'=>'Reactivo 5 de 5','question'=>'¿Cómo debe usarse una base taxonómica en una identificación?','options'=>['Como orientación que se contrasta con rasgos observados','Como reemplazo de toda observación','Como garantía de que una fotografía siempre basta'],'correct'=>0,'feedback'=>'Las bases son herramientas de consulta; la identificación depende de evidencia adecuada.'],
            ]],
            ['slug'=>'plantas-felices-en-casa','title'=>'Lectura: interpretar la luz de una habitación','description'=>'Aprende a observar la luz disponible y relacionarla con el crecimiento antes de mover o regar una planta.','minutes'=>18,'source'=>['University of Minnesota Extension. (s. f.). Lighting for indoor plants.','https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/lighting-for-indoor-plants'],'blocks'=>[
                ['type'=>'text','title'=>'La luz cambia según el lugar','body'=>"La luz que recibe una planta depende de la orientación y distancia de la ventana, obstáculos, estación del año y horas del día. Una habitación que parece luminosa para una persona puede ofrecer poca luz útil para algunas plantas. Observa el lugar durante distintos momentos, en vez de decidir por una sola impresión.\n\nLas ventanas al sur suelen ofrecer más luz directa en el hemisferio norte, pero el clima local, las cortinas y edificios cercanos modifican lo que llega a cada maceta."],
                ['type'=>'text','title'=>'Lee las señales con cautela','body'=>"Un crecimiento alargado o inclinado hacia una ventana puede indicar que la planta busca más luz, pero una señal aislada no confirma la causa. Revisa también cambios recientes, estado del sustrato y si la especie tolera esa exposición.\n\nSi cambias la ubicación, hazlo gradualmente y observa la respuesta. Evita pasar una planta de luz indirecta a sol intenso de golpe; la intensidad nueva puede ser demasiado fuerte para hojas adaptadas a otra condición."],
                ['type'=>'text','title'=>'El riego también depende del ambiente','body'=>"La luz influye en el crecimiento y en la rapidez con que se seca el sustrato, pero no determina por sí sola cuándo regar. Considera especie, tamaño de maceta, drenaje, estación y temperatura. Comprueba la humedad del sustrato antes de añadir agua y vacía el exceso que quede en el plato.\n\nNo uses un calendario rígido como sustituto de observar la planta. Registra la ubicación y los cambios de cuidado para reconocer patrones en tu propio espacio."],
            ]],
            ['slug'=>'plantas-felices-en-casa','title'=>'Práctica: diagnóstico de condiciones de interior','description'=>'Organiza evidencia antes de proponer un ajuste de luz, riego o drenaje.','minutes'=>25,'source'=>['University of Minnesota Extension. (s. f.). Managing insects on indoor plants.','https://extension.umn.edu/garden-and-home/yard-and-garden/yard-and-garden-insects/insects-on-indoor-plants'],'blocks'=>[
                ['type'=>'practice','title'=>'Entrega tu diagnóstico','instructions'=>"Elige una planta de interior o trabaja con el caso: “Una planta junto a una ventana ha inclinado sus tallos hacia el vidrio; el sustrato sigue húmedo y no hay registro de cuándo se regó”.\n\nPrepara un diagnóstico breve con: (1) tres observaciones que puedas verificar; (2) dos causas posibles, expresadas como hipótesis y no como diagnóstico seguro; (3) qué revisarías de luz, humedad del sustrato y drenaje; (4) un solo cambio gradual que probarías primero; y (5) qué registrarías durante los siguientes siete días para evaluar el resultado.\n\nNo recomiendes fertilizantes, pesticidas ni trasplantes sin una señal concreta que lo justifique. Si usas una planta propia, evita compartir datos de ubicación privada."]
            ]],
            ['slug'=>'plantas-felices-en-casa','title'=>'Examen de cuidado de plantas de interior','description'=>'Autoevaluación de cinco reactivos sobre luz, riego, drenaje e inspección preventiva.','minutes'=>20,'source'=>['University of Minnesota Extension. (s. f.). Managing insects on indoor plants.','https://extension.umn.edu/garden-and-home/yard-and-garden/yard-and-garden-insects/insects-on-indoor-plants'],'blocks'=>[
                ['type'=>'quiz','title'=>'Reactivo 1 de 5','question'=>'Antes de mover una planta por falta de luz, ¿qué conviene observar?','options'=>['Ubicación, horas de luz y señales de crecimiento','Solo el color de la maceta','El calendario de riego de otra planta'],'correct'=>0,'feedback'=>'Observa el sitio y la respuesta de la planta antes de cambiar su ubicación.'],
                ['type'=>'quiz','title'=>'Reactivo 2 de 5','question'=>'¿Qué dato es más útil para decidir si revisar el riego?','options'=>['Humedad actual del sustrato y condiciones de la planta','Un día fijo igual para todas las especies','El tamaño de la habitación'],'correct'=>0,'feedback'=>'El riego depende de la planta y su ambiente; comprueba el sustrato.'],
                ['type'=>'quiz','title'=>'Reactivo 3 de 5','question'=>'¿Para qué sirve el orificio de drenaje de una maceta?','options'=>['Permitir que salga el exceso de agua','Mantener agua acumulada en la base','Sustituir la revisión del sustrato'],'correct'=>0,'feedback'=>'El drenaje ayuda a evacuar el exceso; no dejes agua estancada en el plato.'],
                ['type'=>'quiz','title'=>'Reactivo 4 de 5','question'=>'Al encontrar manchas nuevas en hojas, ¿cuál es un primer paso prudente?','options'=>['Inspeccionar la planta y registrar el patrón antes de tratar','Aplicar varios productos a la vez','Trasplantar inmediatamente cualquier planta'],'correct'=>0,'feedback'=>'La inspección permite describir el problema y evitar tratamientos innecesarios.'],
                ['type'=>'quiz','title'=>'Reactivo 5 de 5','question'=>'¿Qué práctica evita confundir una coincidencia con la causa de un cambio?','options'=>['Cambiar varias condiciones a la vez','Anotar condiciones y probar un ajuste gradual','Regar más por precaución'],'correct'=>1,'feedback'=>'Un registro y un cambio controlado facilitan interpretar la respuesta.'],
            ]],
            ['slug'=>'tu-primer-huerto','title'=>'Práctica: diseña un huerto en contenedor','description'=>'Planea un cultivo pequeño según luz, recipiente, drenaje y seguimiento.','minutes'=>25,'source'=>['University of Minnesota Extension. (s. f.). Container gardening for small spaces: big beauty in tiny places.','https://extension.umn.edu/news/container-gardening-small-spaces-big-beauty-tiny-places'],'blocks'=>[
                ['type'=>'practice','title'=>'Entrega tu plan de cultivo','instructions'=>"Diseña un plan para un contenedor comestible que puedas revisar durante una semana. Incluye: (1) horas aproximadas de sol directo en el sitio y cómo las observaste; (2) dos cultivos candidatos compatibles con esa luz y con el tamaño disponible; (3) recipiente, profundidad y orificio de drenaje que comprobarás según las necesidades del cultivo; (4) mezcla para macetas adecuada, no tierra pesada del jardín; y (5) cómo revisarás la humedad y evitarás que quede agua estancada.\n\nAñade un calendario inicial de observación, no un calendario automático de riego. Anota una condición que te haría cambiar el plan y una fuente de cultivo que consultarías antes de sembrar. Las recomendaciones de temporada y variedad pueden cambiar según la región; no asumas que una fecha de siembra sirve para todos los climas."]
            ]],
            ['slug'=>'tu-primer-huerto','title'=>'Lectura: planificar luz, espacio y cosecha','description'=>'Una guía de lectura para elegir cultivos y distribuir un huerto pequeño con expectativas realistas.','minutes'=>18,'source'=>['University of Minnesota Extension. (s. f.). Raised bed gardens.','https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/raised-bed-gardens'],'blocks'=>[
                ['type'=>'text','title'=>'Mide primero el lugar','body'=>"Observa cuántas horas de sol directo recibe el espacio y en qué momento del día. Registra también obstáculos, acceso al agua y posibilidad de mover el recipiente. La luz disponible cambia qué cultivos resultan más adecuados: las plantas de fruto suelen requerir más sol que algunas hojas y hierbas.\n\nLas recomendaciones concretas dependen de especie, variedad y clima. Consulta una guía local de cultivo y el envase de semillas antes de elegir fechas o distancias."],
                ['type'=>'text','title'=>'El recipiente forma parte del sistema','body'=>"El tamaño del recipiente limita el espacio para raíces y la reserva de humedad. Busca una maceta o cama con volumen suficiente para el cultivo y con drenaje funcional. Una mezcla para macetas está formulada para contenedor; la tierra de jardín puede compactarse y comportarse distinto en un recipiente.\n\nAsegura el recipiente en un lugar estable, con acceso seguro para regar. Si vas a cultivar alimentos, usa materiales y sustratos apropiados para ese fin y sigue indicaciones confiables del proveedor."],
                ['type'=>'text','title'=>'Planifica mantenimiento, no solo siembra','body'=>"Los contenedores pueden secarse más rápido que el suelo del jardín. Revisa la humedad de forma frecuente y ajusta según calor, viento, tamaño del recipiente y etapa del cultivo. El objetivo es evitar tanto el secado prolongado como el suelo saturado; no mantengas agua acumulada en la bandeja.\n\nDeja espacio para inspeccionar hojas, registrar fechas y cosechar sin dañar el resto de la planta. Al terminar el ciclo, anota qué funcionó y cambia una variable a la vez en la siguiente siembra."],
            ]],
            ['slug'=>'tu-primer-huerto','title'=>'Examen de huerto en contenedor','description'=>'Autoevaluación de cinco reactivos para comprobar decisiones básicas de planificación y mantenimiento.','minutes'=>20,'source'=>['University of Minnesota Extension. (s. f.). Container gardening for small spaces: big beauty in tiny places.','https://extension.umn.edu/news/container-gardening-small-spaces-big-beauty-tiny-places'],'blocks'=>[
                ['type'=>'quiz','title'=>'Reactivo 1 de 5','question'=>'¿Qué debes medir antes de elegir cultivos para un balcón?','options'=>['Horas de sol directo y espacio disponible','El color del edificio','La distancia a una tienda'],'correct'=>0,'feedback'=>'Luz y espacio ayudan a elegir cultivos apropiados para el sitio.'],
                ['type'=>'quiz','title'=>'Reactivo 2 de 5','question'=>'¿Qué característica es clave para una maceta de cultivo?','options'=>['Orificios que permitan drenar el exceso','Una base sellada que retenga toda el agua','Un recipiente sin espacio para las raíces'],'correct'=>0,'feedback'=>'El exceso de agua debe poder salir del recipiente.'],
                ['type'=>'quiz','title'=>'Reactivo 3 de 5','question'=>'¿Por qué se recomienda una mezcla formulada para macetas?','options'=>['Está pensada para el cultivo en recipientes y su drenaje','Siempre aporta todos los nutrientes por años','No requiere revisar humedad'],'correct'=>0,'feedback'=>'Las mezclas para contenedor tienen propiedades adecuadas para macetas; aun así hay que observar el cultivo.'],
                ['type'=>'quiz','title'=>'Reactivo 4 de 5','question'=>'¿Qué rutina de riego es más razonable para un contenedor?','options'=>['Revisar humedad y ajustar a las condiciones','Regar todos los recipientes con la misma frecuencia fija','Mantener la bandeja llena de agua'],'correct'=>0,'feedback'=>'El calor, el viento, el recipiente y el cultivo cambian la necesidad de agua.'],
                ['type'=>'quiz','title'=>'Reactivo 5 de 5','question'=>'¿Cómo adaptarías el plan si el sitio recibe menos sol del esperado?','options'=>['Revisar cultivos compatibles con esa luz y ajustar la selección','Añadir fertilizante sin revisar nada','Ignorar la diferencia de luz'],'correct'=>0,'feedback'=>'Conviene elegir cultivos según las condiciones reales, no forzar un plan incompatible.'],
            ]],
        ];

        $findModule=$db->prepare('SELECT m.id,c.id course_id FROM course_modules m JOIN courses c ON c.id=m.course_id WHERE c.slug=? ORDER BY m.position LIMIT 1');
        $findLesson=$db->prepare('SELECT id FROM lessons WHERE module_id=? AND title=?');
        $countLessons=$db->prepare('SELECT COUNT(*) FROM lessons WHERE module_id=?');
        $insertLesson=$db->prepare('INSERT INTO lessons(module_id,title,description,position,estimated_minutes,is_required,is_preview) VALUES(?,?,?,?,?,1,0)');
        $insertBlock=$db->prepare('INSERT INTO lesson_blocks(lesson_id,type,title,body,content_data,position,is_required,low_bandwidth) VALUES(?,?,?,?,?,?,1,0)');
        $findReference=$db->prepare('SELECT id FROM content_references WHERE course_id=? AND lesson_id=? AND title=? LIMIT 1');
        $insertReference=$db->prepare('INSERT INTO content_references(course_id,lesson_id,title,url,source_type,notes,position) VALUES(?,?,?,?,\'external\',?,1)');

        foreach($lessons as $lessonData){
            $findModule->execute([$lessonData['slug']]);
            $module=$findModule->fetch(PDO::FETCH_ASSOC);
            if(!$module)continue;
            $moduleId=(int)$module['id'];$courseId=(int)$module['course_id'];
            $findLesson->execute([$moduleId,$lessonData['title']]);
            if($findLesson->fetchColumn())continue;
            $countLessons->execute([$moduleId]);$position=(int)$countLessons->fetchColumn()+1;
            $insertLesson->execute([$moduleId,$lessonData['title'],$lessonData['description'],$position,$lessonData['minutes']]);
            $lessonId=(int)$db->lastInsertId();
            foreach($lessonData['blocks'] as $blockPosition=>$blockData){
                $content=null;$body=null;
                if($blockData['type']==='text')$body=$blockData['body'];
                if($blockData['type']==='practice')$content=json_encode(['instructions'=>$blockData['instructions'],'review_status'=>'pending_review'],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
                if($blockData['type']==='quiz')$content=json_encode(['question'=>$blockData['question'],'options'=>$blockData['options'],'correct_option'=>$blockData['correct'],'feedback'=>$blockData['feedback']],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
                $insertBlock->execute([$lessonId,$blockData['type'],$blockData['title']??null,$body,$content,$blockPosition+1]);
            }
            $sources=[$lessonData['source']];
            if($lessonData['slug']==='botanica-desde-cero')$sources[]=['University of Minnesota Extension. (s. f.). Explore nature in your backyard and beyond.','https://extension.umn.edu/community/family-and-wellness/raising-kids/exploring-nature-in-your-backyard-and-beyond'];
            if($lessonData['slug']==='plantas-felices-en-casa')$sources[]=['University of Minnesota Extension. (s. f.). Lighting for indoor plants.','https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/lighting-for-indoor-plants'];
            foreach($sources as [$sourceTitle,$sourceUrl]){
                $findReference->execute([$courseId,$lessonId,$sourceTitle]);
                if(!$findReference->fetchColumn())$insertReference->execute([$courseId,$lessonId,$sourceTitle,$sourceUrl,'Fuente consultada para ampliar el contenido de la lección.']);
            }
        }
    }

    private static function expandExistingReadings(PDO $db): void
    {
        $expansions = [
            ['botanica-desde-cero','Nombrar para observar','Nombrar para observar',"Antes de asignar un nombre, construye una descripción que pueda revisarse. Observa la planta completa y luego registra cada estructura que realmente está presente: hábito de crecimiento, tallo, disposición de las hojas, forma del margen y nervaduras. Si hay flores o frutos, describe también su forma y cómo se agrupan. No completes con suposiciones los rasgos que no alcanzas a ver.\n\nLos nombres comunes son útiles para conversar, pero pueden cambiar entre regiones y aplicarse a especies distintas. Por eso conviene conservarlos junto al nombre científico consultado, nunca como sustituto automático de una identificación. Busca el nombre en una fuente botánica reconocible, verifica que la descripción coincida con varios rasgos y anota quién publica la información y cuándo la consultaste. Si hay diferencias, registra la duda y busca una segunda fuente."],
            ['botanica-desde-cero','Anatomia visible','Anatomia visible',"Para describir una planta sin dañarla, avanza de lo general a lo particular. Registra primero si crece erguida, rastrera o como trepadora; después observa el tallo y cómo se insertan las hojas. En cada hoja puedes anotar si es simple o compuesta, su forma aproximada, margen, ápice y patrón de nervaduras. Estas palabras ayudan a comparar observaciones, pero por sí solas no garantizan que hayas identificado una especie.\n\nNo todas las estructuras aparecen al mismo tiempo. Una planta joven puede no tener flores ni frutos, y una fotografía puede ocultar detalles importantes. Anota literalmente “no observado” cuando corresponda. Evita arrancar partes para completar la ficha: toma fotografías desde varios ángulos, usa una escala segura si necesitas comparar tamaños y conserva la planta en su entorno. Una descripción cuidadosa reconoce tanto lo que muestra como lo que todavía no permite concluir."],
            ['botanica-desde-cero','Bitacora botánica','Bitacora botánica',"Una bitácora permite comparar la misma planta a lo largo del tiempo. En cada entrada escribe fecha, lugar general, condiciones relevantes y el rasgo que observaste. Describe medidas con una referencia consistente —por ejemplo, una regla colocada junto a la planta sin tocarla— y evita términos ambiguos como “mucho” o “poco” si puedes registrar un valor aproximado. Guarda fotografías con encuadre y distancia parecidos para que la comparación tenga sentido.\n\nSepara en columnas los datos observados, tus preguntas y tus posibles explicaciones. Si cambiaste de lugar la maceta o modificaste el riego, registra cuándo lo hiciste; de otro modo podrías atribuir el cambio a una causa equivocada. Una bitácora no necesita ser complicada: una nota breve y constante suele servir más que una ficha extensa que nunca vuelves a completar. Revisa los registros con frecuencia y señala qué información falta."],
            ['botanica-desde-cero','Comparar sin adivinar','Comparar sin adivinar',"Una comparación útil parte de dos plantas observadas con el mismo criterio. Elige rasgos que puedas describir en ambas: forma de la hoja, margen, nervaduras, disposición, textura visible y características del tallo. Registra el sitio y la fecha, porque luz, edad y estado de desarrollo pueden cambiar el aspecto. Usa fotografías con una escala semejante y no compares una hoja joven con otra madura como si fueran equivalentes.\n\nDespués organiza semejanzas y diferencias en una tabla. Una diferencia aislada —como el tamaño o el tono— no demuestra que sean especies distintas; puede reflejar edad, ambiente, daño o variación natural. Formula una conclusión provisional, indica qué evidencia la apoya y qué dato te falta. Para llegar a una identificación, contrasta varios caracteres con una clave o fuente especializada. Si la evidencia no alcanza, escribe “posible” o “pendiente” en lugar de presentar una conjetura como certeza."],
            ['botanica-desde-cero','De la observación a una pregunta','De la observación a una pregunta',"Una pregunta investigable delimita qué vas a observar, en qué planta o grupo, durante cuánto tiempo y qué compararás. “¿Por qué está mal?” es demasiado amplia y presupone un problema. Una versión más útil podría ser: “¿Cambió el número de hojas nuevas durante las dos semanas posteriores al traslado de esta maceta?”. Esa formulación indica una variable, un periodo y un registro que puedes revisar.\n\nAntes de iniciar, escribe qué esperas encontrar y qué otras explicaciones podrían producir el mismo cambio. Mantén constantes las condiciones que no estás estudiando cuando sea posible y registra cualquier excepción, como una ola de calor o una poda. Repite las observaciones con la misma frecuencia y criterio. Un resultado no demuestra por sí solo una causa, pero puede ayudarte a formular una hipótesis mejor y decidir qué evidencia consultar después."],
            ['botanica-desde-cero','Ficha de identificación responsable','Ficha de identificación responsable',"Una ficha responsable reúne evidencia para que otra persona pueda revisar tu conclusión. Incluye fecha, región general, ambiente, fotografías nítidas de la planta completa y acercamientos de hojas, tallos, flores o frutos disponibles. Describe los rasgos con vocabulario consistente y anota qué partes no estaban presentes. Evita publicar coordenadas de una planta rara o de una propiedad privada.\n\nConsulta una fuente que identifique su autoría y metodología. Compara varios rasgos con la descripción, revisa sinónimos o cambios taxonómicos y registra la fecha de consulta. Las herramientas automáticas de identificación pueden sugerir posibilidades, pero una sugerencia visual no confirma una especie. Si la planta puede ser tóxica, invasora o estar protegida, no la manipules ni la consumas. Cuando haya dudas, conserva la etiqueta “identificación pendiente” y pide revisión a una persona experta."],
            ['plantas-felices-en-casa','Lee la luz','Lee la luz',"La luz disponible no depende únicamente de que una habitación parezca luminosa. Cambia según la orientación de la ventana, la distancia de la maceta, los edificios y árboles exteriores, las cortinas y la estación. Observa el sitio por la mañana, al mediodía y por la tarde; registra si llega sol directo o si la claridad es indirecta. Repite la observación en más de un día antes de sacar conclusiones.\n\nCada especie responde de forma distinta. Compara las condiciones del lugar con una guía de cultivo confiable para esa planta y observa su crecimiento: tallos alargados, inclinación persistente o pérdida de vigor pueden ser señales que conviene investigar, no diagnósticos por sí solos. Si necesitas cambiarla, hazlo gradualmente y observa la respuesta durante varios días. No pases de golpe una planta adaptada a sombra a sol intenso, porque las hojas pueden resentir ese cambio."],
            ['plantas-felices-en-casa','Riego y drenaje','Riego y drenaje',"Regar bien significa atender la humedad que necesita esa planta, no seguir un día fijo de la semana. Antes de añadir agua, revisa el sustrato con el dedo o con una herramienta limpia a una profundidad prudente, y observa el peso de la maceta y el estado general de la planta. La superficie puede secarse antes que el interior; por eso una sola señal no siempre basta. Registra cuánto tarda en secarse en tu casa y vuelve a revisar después de cambiarla de lugar o de estación.\n\nUna maceta funcional debe permitir que el exceso de agua salga. Si usas un cubremaceta o plato, vacía el agua acumulada después del riego para evitar que las raíces permanezcan encharcadas. El exceso de humedad y el drenaje deficiente pueden contribuir a problemas de raíz, mientras que un sustrato seco por mucho tiempo también estresa la planta. Ajusta con calma, una variable a la vez, y consulta las necesidades particulares de la especie."],
            ['plantas-felices-en-casa','Propagación responsable','Propagación responsable',"La propagación por esqueje no funciona igual para todas las plantas. Antes de cortar, identifica la especie y revisa qué tejido puede producir raíces y brotes nuevos. En muchas plantas de tallo, el nudo —la zona donde se originan hojas o yemas— es esencial; una hoja separada sin tejido de crecimiento puede no formar una planta nueva. Usa herramientas limpias y afiladas, y toma un esqueje solo si la planta madre está sana y tienes permiso para hacerlo.\n\nInvestiga si el método recomendado es en agua, sustrato u otra técnica y prepara el recipiente con higiene y drenaje adecuados. Mantén condiciones compatibles con la especie, evita cambios extremos de luz y no confundas raíces iniciales con un sistema ya establecido. Etiqueta el esqueje con nombre provisional y fecha, registra cambios y ten paciencia: el tiempo de enraizamiento varía. Si no estás seguro de la identificación o toxicidad, evita manipularla y consulta una fuente confiable."],
            ['plantas-felices-en-casa','Diagnostica antes de cambiar cuidados','Diagnostica antes de cambiar cuidados',"Un síntoma visible puede tener más de una causa. Hojas amarillas, manchas o marchitez pueden relacionarse con riego, luz, raíces, temperatura, plagas o cambios recientes. Describe primero qué hojas presentan el síntoma, desde cuándo, si avanza y qué aspecto tiene el resto de la planta. Comprueba la humedad del sustrato, el drenaje y la ubicación; inspecciona también ambas caras de las hojas sin aplicar tratamientos preventivos.\n\nAnota los cuidados recientes y separa los hechos de las hipótesis. Por ejemplo, “el sustrato sigue húmedo tres días después del riego” es un dato; “tiene una enfermedad” todavía requiere evidencia. Elige una intervención pequeña y razonable, como corregir agua estancada o mejorar la observación de luz, y registra la respuesta antes de hacer otro cambio. Si el daño se extiende o sospechas una plaga, busca una guía de diagnóstico especializada y confirma la identificación antes de usar productos."],
            ['plantas-felices-en-casa','Trasplanta solo cuando haga falta','Trasplanta solo cuando haga falta',"Trasplantar puede ayudar cuando las raíces han ocupado el recipiente o cuando el sustrato perdió estructura, pero hacerlo por rutina añade estrés. Revisa señales en conjunto: raíces que salen por los orificios, agua que atraviesa de inmediato, crecimiento detenido junto con otras señales o un cepellón muy compacto. Ninguna señal aislada obliga a cambiar de maceta; primero considera la especie, la estación y el estado general.\n\nElige un recipiente apenas mayor que el actual y con orificios de drenaje. Una maceta demasiado grande retiene más humedad alrededor de raíces que todavía no ocupan ese volumen. Usa una mezcla apropiada para la especie y humedece según las indicaciones de cultivo. Manipula el cepellón con cuidado, conserva raíces sanas y evita fertilizar de inmediato si la planta está estresada. Después colócala en condiciones estables y observa su recuperación antes de realizar otros cambios."],
            ['plantas-felices-en-casa','Plan de cuidado semanal','Plan de cuidado semanal',"Una rutina útil es una lista de observación, no una orden automática de regar. Elige un día para revisar las plantas y apunta humedad del sustrato, luz, hojas nuevas o dañadas, presencia de insectos y agua en los platos. Decide si alguna acción es necesaria después de revisar los datos. La frecuencia de riego cambia con la especie, el tamaño de maceta, la mezcla, la temperatura, la estación y la luz que recibe.\n\nAgrupa plantas solo si sus necesidades son realmente parecidas. Mantén las etiquetas visibles, limpia hojas secas con cuidado y revisa zonas ocultas donde pueden aparecer plagas. Si haces un ajuste, anota fecha y motivo; luego observa si mejoró la condición. Evita cambiar simultáneamente ubicación, riego y fertilizante, pues después será difícil saber qué influyó. Una rutina flexible permite responder a cada planta sin descuidar la seguridad de mascotas o niños."],
            ['tu-primer-huerto','Elige según tu luz','Elige según tu luz',"Antes de elegir semillas, observa cuántas horas de sol directo recibe el lugar y en qué horario. Anota si hay sombra de edificios, árboles o barandales, y repite la observación en días distintos. Los cultivos de fruto como tomate y pimiento suelen demandar más luz que algunas hojas, pero las necesidades concretas dependen de especie y variedad. Consulta guías locales, porque clima, estación y latitud cambian las recomendaciones.\n\nRelaciona la luz con el espacio y el tiempo que puedes dedicar. En un sitio pequeño, empieza con pocos cultivos y considera hierbas o variedades compactas si sus requisitos coinciden con el lugar. No intentes compensar la falta de luz con más fertilizante: eso no sustituye las condiciones necesarias para el crecimiento. Si cambian las estaciones, vuelve a medir la luz antes de concluir que una planta falló por el riego."],
            ['tu-primer-huerto','Contenedor funcional','Contenedor funcional',"Un buen recipiente ofrece volumen suficiente para las raíces, estabilidad y salida para el exceso de agua. Revisa las indicaciones de cultivo para decidir profundidad y tamaño; no hay una medida única para todas las especies. Los contenedores pequeños se secan con mayor rapidez y pueden requerir vigilancia más frecuente, especialmente con calor o viento. Antes de llenarlo, confirma que los orificios no estén obstruidos y que el agua pueda salir sin dañar el espacio donde se coloca.\n\nUsa una mezcla formulada para macetas o camas elevadas según el caso. La tierra de jardín puede compactarse y drenar de manera distinta en un volumen cerrado. Humedece la mezcla de forma pareja, sin dejarla saturada, y etiqueta cada recipiente con cultivo y fecha. Piensa también en el peso, el acceso para regar y el material apto para cultivar alimentos. Una solución sencilla que puedes mantener suele ser mejor que un sistema grande difícil de revisar."],
            ['tu-primer-huerto','Riego observacional','Riego observacional',"Los contenedores tienen un volumen limitado de sustrato y pueden secarse más rápido que un bancal en suelo, aunque la rapidez depende del tamaño, material, cultivo, temperatura y viento. Revisa la humedad antes de regar y observa si el agua entra de forma uniforme o sale inmediatamente por un costado. Riega de manera que la mezcla reciba humedad y deja que el excedente drene; no mantengas la base sumergida.\n\nAnota fechas y condiciones durante las primeras semanas para conocer cómo responde tu recipiente. Evita convertir esa primera frecuencia en una regla fija: una semana nublada y fresca no equivale a varios días cálidos y ventosos. Las plantas recién sembradas y las ya desarrolladas tampoco tienen exactamente las mismas necesidades. Si el sustrato se seca demasiado pronto, revisa volumen, exposición y mezcla antes de aumentar el agua sin límite."],
            ['tu-primer-huerto','Siembra y profundidad','Siembra y profundidad',"La profundidad y separación de siembra dependen del cultivo y de las instrucciones del proveedor. Lee el paquete de semillas antes de sembrar y registra variedad, fecha y cantidad. Algunas semillas necesitan luz para germinar y se colocan cerca de la superficie; otras requieren cubrirse más. No apliques una misma profundidad a todas. Si trasplantas plántulas, conserva el cepellón y sigue recomendaciones específicas para esa especie.\n\nMantén la mezcla húmeda según las necesidades de germinación, sin saturarla. Etiqueta el recipiente para no confundir brotes con malezas y observa la emergencia durante el intervalo sugerido. Una vez que las plantas crecen, revisa si necesitan espacio adicional y evita tirar de las raíces al ralear. Las fechas de siembra también varían por clima; utiliza una guía regional actualizada en vez de tomar el calendario de otro lugar como universal."],
            ['tu-primer-huerto','Observa plagas antes de intervenir','Observa plagas antes de intervenir',"Inspecciona las plantas de forma periódica, especialmente el envés de las hojas, brotes tiernos y uniones de tallos. Registra insectos, telarañas, melaza, manchas, agujeros y qué partes están afectadas. Fotografía el patrón y revisa si aparece en una sola planta o en varias. Algunos daños se parecen entre sí, así que evita decidir que existe una plaga solo por una hoja amarilla o un agujero aislado.\n\nSi sospechas un organismo dañino, confirma su identidad y evalúa el nivel de daño antes de actuar. Aísla una maceta si es posible y consulta un servicio de extensión o guía local. No mezcles productos ni excedas la etiqueta: sigue exactamente las instrucciones y precauciones del producto autorizado. En cultivos comestibles, revisa el intervalo de seguridad antes de cosechar. La observación temprana y una identificación correcta ayudan a elegir medidas proporcionales y evitar afectar insectos benéficos."],
            ['tu-primer-huerto','Cosecha y evaluación del ciclo','Cosecha y evaluación del ciclo',"Cosechar en el momento adecuado depende del cultivo y de la parte que se consume. Consulta una guía específica para reconocer tamaño, color o firmeza de madurez; no te bases únicamente en una fotografía. Usa herramientas limpias cuando sean necesarias y evita arrancar tallos que puedan seguir produciendo. Lava las manos y los alimentos según recomendaciones de inocuidad antes de consumirlos.\n\nAl terminar cada ciclo, revisa tus registros: fecha de siembra, luz observada, riego, incidencias y cosecha. Compara lo que ocurrió con el plan inicial y anota qué hipótesis se confirmó o quedó sin respuesta. Cambia una variable en la siguiente siembra —por ejemplo, ubicación o variedad— para aprender qué influyó. Considera también condiciones externas como calor inusual o sombra nueva. Un registro honesto te permite ajustar expectativas y elegir mejor sin atribuir todo resultado a una sola causa."],
            ['botanica-desde-cero','Lectura: construir una observación botánica','Empieza por describir',"Al preparar una descripción, avanza con un orden constante: forma general de crecimiento, tallo, disposición de las hojas y rasgos de cada hoja. Usa palabras que indiquen qué observaste y evita términos que ya interpreten una causa, como “marchita por falta de agua”. En su lugar escribe qué aspecto tiene y qué condición mediste. Si tomas fotografías, incluye una vista completa y acercamientos enfocados; conserva un encuadre comparable para futuras visitas.\n\nUna buena observación no intenta decirlo todo. Selecciona rasgos útiles para responder tu pregunta y registra también las limitaciones: luz cambiante, partes ocultas o falta de flores. No recolectes especies desconocidas para obtener una mejor imagen. Puedes volver a la planta en otro momento y completar la ficha cuando una estructura aparezca."],
            ['botanica-desde-cero','Lectura: construir una observación botánica','Separa evidencia e interpretación',"La evidencia describe un dato que alguien podría volver a observar; la interpretación propone qué podría significar. Mantener ambas cosas separadas no invalida tus ideas: permite analizarlas con más cuidado. Escribe primero el dato y luego, en otro apartado, una o varias explicaciones posibles. Considera qué evidencia apoyaría cada explicación y qué observación podría contradecirla.\n\nCuando compares varios días, utiliza el mismo criterio y registra las condiciones que cambiaron. Una asociación temporal no demuestra por sí sola causalidad; por ejemplo, que una hoja nueva aparezca después de un riego no prueba que el riego fuera la única causa. Puedes diseñar nuevas observaciones para reducir la incertidumbre y consultar una fuente especializada antes de actuar sobre la planta."],
            ['botanica-desde-cero','Lectura: construir una observación botánica','Usa la identificación como una hipótesis',"Los portales taxonómicos reúnen nombres, sinónimos y datos botánicos, pero una búsqueda no reemplaza la comparación de rasgos. Revisa qué fuente respalda el nombre aceptado, si muestra distribución pertinente y si los caracteres descritos coinciden con tu ejemplar. Ten en cuenta que la clasificación puede cambiar a medida que se actualiza la investigación. Por eso registra la versión o fecha de consulta cuando sea relevante.\n\nSi varias especies parecen posibles, anota las diferencias que necesitas observar y busca una clave regional o una persona experta. No uses una aplicación de reconocimiento como confirmación única, y nunca pruebes una planta silvestre por una identificación tentativa. En la ficha final puedes comunicar un nivel de confianza y explicar la evidencia; reconocer lo que aún no sabes es parte del trabajo botánico responsable."],
            ['plantas-felices-en-casa','Lectura: interpretar la luz de una habitación','La luz cambia según el lugar',"Para describir un sitio, distingue luz directa —el sol incide sobre la hoja— de luz indirecta intensa o de un espacio con poca iluminación. Registra orientación de la ventana, distancia, obstáculos y horas aproximadas en que el sol entra. Las estaciones modifican el ángulo y duración de la luz; una ubicación que funciona en verano puede cambiar en invierno. Si utilizas una lámpara de cultivo, apunta distancia y horario según instrucciones del fabricante.\n\nCompara esas condiciones con las necesidades de la especie, no con la preferencia de otra planta. Una cortina translúcida o un árbol exterior puede reducir intensidad aun cuando la ventana parezca grande. Una medición con teléfono ofrece solo una estimación si el sensor no está calibrado; úsala para comparar lugares, no como valor absoluto."],
            ['plantas-felices-en-casa','Lectura: interpretar la luz de una habitación','Lee las señales con cautela',"El crecimiento alargado, los entrenudos amplios o una inclinación persistente pueden ser indicios de que la planta recibe luz insuficiente, pero también influyen la especie, su edad y su historia de cultivo. Hojas pálidas, bordes secos o manchas pueden tener otras causas. Observa varias señales y compara los brotes nuevos con el crecimiento anterior antes de decidir.\n\nSi cambias la planta de lugar, evita pasarla de manera abrupta a sol directo fuerte. Acostúmbrala gradualmente durante varios días, siempre que las necesidades de la especie lo permitan, y revisa si aparecen daños. Registra la posición anterior y nueva, así como cualquier otra variable que cambies. Si hay síntomas preocupantes, busca una guía específica o diagnóstico especializado en lugar de tratar por intuición."],
            ['botanica-desde-cero','Práctica: expediente de una planta','Entrega tu expediente',"Una ficha clara facilita que otra persona comprenda tu proceso y dé retroalimentación útil. Usa encabezados, frases completas y unidades aproximadas cuando midas. Distingue las observaciones directas de las imágenes tomadas por otra persona o de las sugerencias automáticas. Incluye una conclusión provisional y explica qué rasgos la apoyan; si no puedes identificar la planta, señala qué evidencia falta en vez de forzar un nombre.\n\nAntes de enviar, revisa que no hayas compartido datos personales o la ubicación precisa de una planta vulnerable. Mantén la respuesta en un tono descriptivo y evita recomendar usos medicinales o alimentarios basados en una identificación incierta. Tu expediente se evalúa por la calidad del registro y el reconocimiento de límites, no por acertar un nombre a toda costa."],
            ['plantas-felices-en-casa','Práctica: diagnóstico de condiciones de interior','Entrega tu diagnóstico',"Organiza la respuesta con subtítulos: “Evidencia”, “Hipótesis”, “Qué revisaré”, “Primer ajuste” y “Seguimiento”. Para cada hipótesis, explica qué observación la haría más probable y qué dato necesitas conseguir. Prioriza comprobar condiciones simples y seguras antes de comprar productos o intervenir raíces.\n\nDefine un registro que puedas repetir: fecha, estado del sustrato, ubicación, síntomas y fotografía desde el mismo ángulo. Un periodo breve de seguimiento no siempre basta para confirmar la causa; indica qué resultado esperarías y cuándo buscarías ayuda adicional. Si analizas una planta propia, comparte solo los datos necesarios y no publiques información privada del hogar."],
            ['tu-primer-huerto','Práctica: diseña un huerto en contenedor','Entrega tu plan de cultivo',"Presenta el plan en una tabla sencilla con cultivo candidato, luz que requiere según tu fuente, espacio disponible, recipiente y forma de revisar humedad. Distingue la luz que mediste de la recomendación publicada. Incluye al menos una alternativa si el lugar recibe menos sol de lo esperado. No prometas una cosecha específica: el resultado depende de variedad, clima, calidad de semilla y cuidados.\n\nCierra con un calendario de observación semanal y una lista de materiales seguros. Antes de sembrar, verifica profundidad, espaciamiento y fecha con instrucciones adaptadas a tu región. Si el contenedor estará en un balcón, considera peso mojado, viento y estabilidad para prevenir accidentes."],
            ['tu-primer-huerto','Lectura: planificar luz, espacio y cosecha','Mide primero el lugar',"Haz una cuadrícula o croquis simple del espacio y señala las horas aproximadas de sol directo, zonas de sombra y acceso al agua. Observa en varios días, pues nubes y obstáculos producen variaciones. Compara la cantidad de luz con requerimientos publicados para la especie y variedad que te interesa. Algunas guías de extensión señalan que ciertos cultivos de fruto necesitan varias horas de sol, mientras que algunas hojas toleran condiciones menos soleadas; verifica siempre la recomendación regional.\n\nNo confundas “hay claridad” con “recibe sol directo”. Si el sitio cambia durante la temporada, repite la medición y ajusta tu selección. Empieza con pocos recipientes para aprender cómo responde el microclima de tu casa."],
            ['tu-primer-huerto','Lectura: planificar luz, espacio y cosecha','El recipiente forma parte del sistema',"El recipiente y el sustrato trabajan juntos: el volumen permite el desarrollo de raíces y reserva humedad, mientras los orificios y la mezcla permiten que salga el exceso de agua. Lee las indicaciones del cultivo para elegir profundidad y tamaño. Asegúrate de que el recipiente sea resistente y que pueda colocarse sin bloquear pasillos o salidas. Una cama elevada y una maceta pequeña no se comportan igual en cuanto a temperatura y secado.\n\nUtiliza una mezcla formulada para contenedor, no tierra compacta extraída del jardín. Revisa etiquetas para confirmar que el producto sea adecuado para cultivar alimentos y sigue sus instrucciones. Considera acceso al agua, posibilidad de mover el recipiente y peso una vez saturado. Diseña un sistema sencillo que puedas mantener incluso en semanas ocupadas."],
            ['tu-primer-huerto','Lectura: planificar luz, espacio y cosecha','Planifica mantenimiento, no solo siembra',"El trabajo no termina al cubrir las semillas. Programa revisiones para observar emergencia, humedad, coloración, plagas y estabilidad del recipiente. Los contenedores pueden secarse más rápido que una cama en tierra, por lo que conviene revisar con mayor frecuencia, pero no regar automáticamente sin comprobar. Si el agua sale enseguida, revisa si la mezcla se ha vuelto hidrofóbica o si existe un canal; si permanece saturada, comprueba drenaje y bandeja.\n\nAl cosechar, consulta el tamaño o estado recomendado para cada cultivo y utiliza herramientas limpias si hacen falta. Lleva un registro de fechas y rendimiento real; después cambia solo una o dos variables que puedas observar. Así aprenderás si el resultado estuvo relacionado con la luz, la variedad, el riego o una condición inesperada, en vez de atribuirlo a una sola causa."],
        ];
        $find=$db->prepare('SELECT b.id,b.body FROM lesson_blocks b JOIN lessons l ON l.id=b.lesson_id JOIN course_modules m ON m.id=l.module_id JOIN courses c ON c.id=m.course_id WHERE c.slug=? AND l.title=? AND b.title=? AND b.type=\'text\' ORDER BY b.position LIMIT 1');
        $update=$db->prepare('UPDATE lesson_blocks SET body=? WHERE id=?');
        $marker='Profundización de la lectura:';
        foreach($expansions as [$slug,$lessonTitle,$blockTitle,$text]){
            $find->execute([$slug,$lessonTitle,$blockTitle]);
            $block=$find->fetch(PDO::FETCH_ASSOC);
            if(!$block)continue;
            $body=(string)$block['body'];
            if(str_contains($body,$marker))continue;
            $update->execute([rtrim($body)."\n\n{$marker}\n{$text}",(int)$block['id']]);
        }
    }

